fn wrapping_add_hlp<T>(x: T, y: T) -> T
where
    T: AsPrimitive<Field>,
    Field: AsPrimitive<T>,
{
    AsPrimitive::as_(x.as_() + y.as_())
}

fn wrapping_sub_hlp<T>(x: T, y: T) -> Field
where
    T: AsPrimitive<Field>,
{
    //340282366920938463463374607431768211456 is 2^128, it is used to avoid underflow
    x.as_() + 340282366920938463463374607431768211456 - y.as_()
}

fn wrapping_mul_hlp<T>(x: T, y: T) -> T
where
    T: AsPrimitive<Field>,
    Field: AsPrimitive<T>,
{
    AsPrimitive::as_(x.as_() * y.as_())
}

global two_pow_64: u128 = 0x10000000000000000;
/// Splits a 128 bits number into two 64 bits limbs
unconstrained fn split64(x: u128) -> (u64, u64) {
    let lo = x as u64;
    let hi = (x / two_pow_64) as u64;
    (lo, hi)
}

/// Split a 128 bits number into two 64 bits limbs
/// It will fail if the number is more than 128 bits
fn split_into_64_bit_limbs(x: u128) -> (u64, u64) {
    // Safety: the limbs are constrained below
    let (x_lo, x_hi) = unsafe { split64(x) };
    assert(x as Field == x_lo as Field + x_hi as Field * two_pow_64 as Field);
    (x_lo, x_hi)
}

#[field(bn254)]
fn wrapping_mul128_hlp(x: u128, y: u128) -> u128 {
    let (x_lo, x_hi) = split_into_64_bit_limbs(x);
    let (y_lo, y_hi) = split_into_64_bit_limbs(y);
    // Multiplication using the limbs:(x_lo + 2**64*x_hi)*(y_lo + 2**64*y_hi)=x_lo*y_lo+...
    // and skipping the terms over 2**128
    // Working with u64 limbs ensures that we cannot overflow the field modulus.
    let low = x_lo as Field * y_lo as Field;
    let lo = low as u64 as Field;
    let carry = (low - lo) / two_pow_64 as Field;
    let high = x_lo as Field * y_hi as Field + x_hi as Field * y_lo as Field + carry;
    let hi = high as u64 as Field;
    (lo + two_pow_64 as Field * hi) as u128
}

mod tests {
    #[test(should_fail_with = "custom message")]
    fn test_static_assert_custom_message() {
        crate::static_assert(1 == 2, "custom message");
    }

    mod arithmetic {
        use crate::ops::arith::{Add, Div, Mul, Neg, Rem, Sub};
        #[test]
        fn test_basic_arithmetic_traits() {
            // add
            assert_eq(5.add(3), 8);
            assert_eq(0u8.add(255u8), 255u8);
            assert_eq(42.add(58), 100);

            // sub
            assert_eq(10.sub(3), 7);
            assert_eq(100.sub(42), 58);

            // mul
            assert_eq(6.mul(7), 42);

            // div
            assert_eq(15.div(3), 5);
            assert_eq(10u8.div(3u8), 3u8);
            assert_eq(15.div(3), 5);

            // rem (Field doesn't implement Rem)
            assert_eq(17u64.rem(5u64), 2u64);
            assert_eq(10u8.rem(3u8), 1u8);

            // neg
            assert_eq(42.neg(), -42);
            assert_eq((-10).neg(), 10);
            assert_eq(42.neg(), -42);
        }

        #[test]
        fn test_division() {
            // test division by one
            assert_eq(42.div(1), 42);
            assert_eq(0.div(1), 0);
            assert_eq(255u8.div(1u8), 255u8);

            // test division by self
            assert_eq(42.div(42), 1);
            assert_eq(1.div(1), 1);

            // test remainder (Field doesn't implement Rem)
            assert_eq(42u32.rem(42u32), 0u32);
            assert_eq(0u16.rem(42u16), 0u16);
            assert_eq(1u64.rem(42u64), 1u64);
        }

        // Per-operator overflow corners. The signed `iN::MIN` corners pin down
        // compiler-side overflow detection on the trait dispatch path: the
        // trait impls are one-line delegations to the built-in operators and
        // rely entirely on the compiler's lowering to emit the two's-complement
        // overflow constraints. These tests trip CI on any future SSA pass
        // that drops one of those constraints.
        //
        // Each case pins the exact runtime message via `should_fail_with`, so a
        // regression that starts failing for the *wrong* reason (a divide by
        // zero, or a panic in unrelated code) is caught too, rather than being
        // accepted as "it failed somehow". The matcher is a case-insensitive
        // substring, so the same string works under both ACIR and Brillig even
        // though Brillig capitalizes the divide/remainder messages.

        mod add {
            use crate::ops::arith::Add;

            // `MAX + 1` is one past the largest representable value, so the
            // range check on the sum rejects it. For unsigned this is a wrap
            // past `2^bits - 1`; for signed it steps out of `[MIN, MAX]`.

            #[test(should_fail_with = "attempt to add with overflow")]
            fn u8_overflow() {
                let _ = 255u8.add(1u8);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn u16_overflow() {
                let _ = 65535u16.add(1u16);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn i8_overflow() {
                let _ = 127i8.add(1i8);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn i16_overflow() {
                let _ = 32767i16.add(1i16);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn i32_overflow() {
                let _ = 2147483647i32.add(1i32);
            }

            #[test(should_fail_with = "attempt to add with overflow")]
            fn i64_overflow() {
                let _ = 9223372036854775807i64.add(1i64);
            }
        }

        mod sub {
            use crate::ops::arith::Sub;

            // Subtraction underflows past the type's minimum: `0 - 1` for
            // unsigned (a borrow below zero), and `MIN - 1` for signed (one step
            // below the most-negative value).

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn u8_overflow() {
                let _ = 0u8.sub(1u8);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn u16_overflow() {
                let _ = 0u16.sub(1u16);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn i8_overflow() {
                let val: i8 = -128;
                let _ = val.sub(1i8);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn i16_overflow() {
                let val: i16 = -32768;
                let _ = val.sub(1i16);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn i32_overflow() {
                let val: i32 = -2147483648;
                let _ = val.sub(1i32);
            }

            #[test(should_fail_with = "attempt to subtract with overflow")]
            fn i64_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.sub(1i64);
            }
        }

        mod mul {
            use crate::ops::arith::Mul;

            // Unsigned `MAX * 2` exceeds the maximum. The signed corner is
            // `MIN * -1`: the true product is `-MIN == 2^(bits-1)`, exactly one
            // past the signed maximum `2^(bits-1) - 1`, so it is unrepresentable.
            // This is the same range asymmetry that makes negating MIN overflow.

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn u8_overflow() {
                let _ = 255u8.mul(2u8);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn u16_overflow() {
                let _ = 65535u16.mul(2u16);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn i8_min_times_neg_one_overflow() {
                let val: i8 = -128;
                let _ = val.mul(-1i8);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn i16_min_times_neg_one_overflow() {
                let val: i16 = -32768;
                let _ = val.mul(-1i16);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn i32_min_times_neg_one_overflow() {
                let val: i32 = -2147483648;
                let _ = val.mul(-1i32);
            }

            #[test(should_fail_with = "attempt to multiply with overflow")]
            fn i64_min_times_neg_one_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.mul(-1i64);
            }
        }

        mod div {
            use crate::ops::arith::Div;

            // `MIN / -1` is the only division that overflows: the quotient is
            // `-MIN == 2^(bits-1)`, one past the signed maximum. (Division by
            // zero is a distinct error and is not what these cases exercise.)

            #[test(should_fail_with = "attempt to divide with overflow")]
            fn i8_min_by_neg_one_overflow() {
                let val: i8 = -128;
                let _ = val.div(-1i8);
            }

            #[test(should_fail_with = "attempt to divide with overflow")]
            fn i16_min_by_neg_one_overflow() {
                let val: i16 = -32768;
                let _ = val.div(-1i16);
            }

            #[test(should_fail_with = "attempt to divide with overflow")]
            fn i32_min_by_neg_one_overflow() {
                let val: i32 = -2147483648;
                let _ = val.div(-1i32);
            }

            #[test(should_fail_with = "attempt to divide with overflow")]
            fn i64_min_by_neg_one_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.div(-1i64);
            }
        }

        mod rem {
            use crate::ops::arith::Rem;

            // `MIN % -1` is mathematically 0, but it is computed via the same
            // `MIN / -1` division that overflows, so the operation is rejected
            // rather than silently yielding 0. This matches Rust, where
            // `iN::MIN % -1` also overflows.

            #[test(should_fail_with = "attempt to calculate the remainder with overflow")]
            fn i8_min_by_neg_one_overflow() {
                let val: i8 = -128;
                let _ = val.rem(-1i8);
            }

            #[test(should_fail_with = "attempt to calculate the remainder with overflow")]
            fn i16_min_by_neg_one_overflow() {
                let val: i16 = -32768;
                let _ = val.rem(-1i16);
            }

            #[test(should_fail_with = "attempt to calculate the remainder with overflow")]
            fn i32_min_by_neg_one_overflow() {
                let val: i32 = -2147483648;
                let _ = val.rem(-1i32);
            }

            #[test(should_fail_with = "attempt to calculate the remainder with overflow")]
            fn i64_min_by_neg_one_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.rem(-1i64);
            }
        }

        mod neg {
            use crate::ops::arith::Neg;

            // Negating `MIN` overflows because the two's-complement range is
            // asymmetric: `-MIN == 2^(bits-1)` has no representable positive
            // counterpart (the maximum is only `2^(bits-1) - 1`). MIN is the
            // unique value with this property, so it is the only negation that
            // fails. The wording of the failure depends on the execution path:
            // the comptime interpreter reports "attempt to negate with
            // overflow", while ACIR/Brillig lower unary `-` to `0 - x` and so
            // report "attempt to subtract with overflow". Both share
            // "with overflow", which is what these cases assert on.

            #[test(should_fail_with = "with overflow")]
            fn i8_min_overflow() {
                let val: i8 = -128;
                let _ = val.neg();
            }

            #[test(should_fail_with = "with overflow")]
            fn i16_min_overflow() {
                let val: i16 = -32768;
                let _ = val.neg();
            }

            #[test(should_fail_with = "with overflow")]
            fn i32_min_overflow() {
                let val: i32 = -2147483648;
                let _ = val.neg();
            }

            #[test(should_fail_with = "with overflow")]
            fn i64_min_overflow() {
                let val: i64 = -9223372036854775808;
                let _ = val.neg();
            }
        }

        #[test]
        fn test_field() {
            let zero: Field = 0;
            let one: Field = 1;

            // test Field basic operations
            assert_eq(zero.add(one), one);
            assert_eq(one.add(zero), one);
            assert_eq(one.sub(one), zero);
            assert_eq(one.mul(one), one);
            assert_eq(one.div(one), one);
            assert_eq(zero.neg(), zero);
            assert_eq(one.neg(), -one);
        }

    }

    mod wrapping_arithmetic {
        use crate::ops::arith::{Add, Div, Mul, Neg, Sub, WrappingAdd, WrappingMul, WrappingSub};
        #[test]
        fn test_wrapping_add() {
            assert_eq(255u8.wrapping_add(1u8), 0u8);
            assert_eq(255u8.wrapping_add(255u8), 254u8);
            assert_eq(0u8.wrapping_add(0u8), 0u8);
            assert_eq(128u8.wrapping_add(128u8), 0u8);

            // test u16 wrapping add
            assert_eq(65535u16.wrapping_add(1u16), 0u16);
            assert_eq(65535u16.wrapping_add(65535u16), 65534u16);

            // test u32 wrapping add
            assert_eq(0xffffffffu32.wrapping_add(1u32), 0u32);
            assert_eq(0xffffffffu32.wrapping_add(0xffffffffu32), 0xfffffffeu32);

            // test u64 wrapping add
            assert_eq(0xffffffffffffffffu64.wrapping_add(1u64), 0u64);
            assert_eq(
                0xffffffffffffffffu64.wrapping_add(0xffffffffffffffffu64),
                0xfffffffffffffffeu64,
            );

            // test u128 wrapping add
            assert_eq(0xffffffffffffffffffffffffffffffffu128.wrapping_add(1u128), 0u128);

            // test signed types
            assert_eq(127i8.wrapping_add(1i8), -128i8);
            let val: i8 = -128;
            assert_eq(val.wrapping_add(-1i8), 127i8);

            // test Field wrapping add
            let forty_two: Field = 42;
            let fifty_eight: Field = 58;
            let hundred: Field = 100;
            let neg_two: Field = -2;
            let two: Field = 2;
            let zero: Field = 0;
            let neg_two_hundred: Field = -200;
            let neg_one_ninety_eight: Field = -198;
            assert_eq(forty_two.wrapping_add(fifty_eight), hundred);
            assert_eq(neg_two.wrapping_add(two), zero);
            assert_eq(neg_two_hundred.wrapping_add(two), neg_one_ninety_eight);
        }

        #[test]
        fn test_wrapping_sub() {
            assert_eq(0u8.wrapping_sub(1u8), 255u8);
            assert_eq(255u8.wrapping_sub(255u8), 0u8);
            assert_eq(0u8.wrapping_sub(0u8), 0u8);
            assert_eq(1u8.wrapping_sub(2u8), 255u8);

            // test u16 wrapping sub
            assert_eq(0u16.wrapping_sub(1u16), 65535u16);
            assert_eq(65535u16.wrapping_sub(65535u16), 0u16);

            // test u32 wrapping sub
            assert_eq(0u32.wrapping_sub(1u32), 0xffffffffu32);
            assert_eq(0xffffffffu32.wrapping_sub(0xffffffffu32), 0u32);

            // test u64 wrapping sub
            assert_eq(0u64.wrapping_sub(1u64), 0xffffffffffffffffu64);
            assert_eq(0xffffffffffffffffu64.wrapping_sub(0xffffffffffffffffu64), 0u64);

            // test u128 wrapping sub
            assert_eq(0u128.wrapping_sub(1u128), 0xffffffffffffffffffffffffffffffffu128);

            // test signed types
            let val: i8 = -128;
            assert_eq(val.wrapping_sub(1i8), 127i8);
            assert_eq(127i8.wrapping_sub(-1i8), -128i8);

            // test Field wrapping sub
            let forty_two: Field = 42;
            let fifty_eight: Field = 58;
            let neg_sixteen: Field = -16;
            assert_eq(forty_two.wrapping_sub(fifty_eight), neg_sixteen);
        }

        #[test]
        fn test_wrapping_mul() {
            let zero: u128 = 0;
            let one: u128 = 1;
            let two_pow_64: u128 = 0x10000000000000000;
            let u128_max: u128 = 0xffffffffffffffffffffffffffffffff;

            assert_eq(zero, zero.wrapping_mul(one));
            assert_eq(zero, one.wrapping_mul(zero));
            assert_eq(one, one.wrapping_mul(one));
            assert_eq(zero, zero.wrapping_mul(two_pow_64));
            assert_eq(zero, two_pow_64.wrapping_mul(zero));
            assert_eq(two_pow_64, two_pow_64.wrapping_mul(one));
            assert_eq(two_pow_64, one.wrapping_mul(two_pow_64));
            assert_eq(zero, two_pow_64.wrapping_mul(two_pow_64));
            assert_eq(one, u128_max.wrapping_mul(u128_max));

            // test u8 wrapping mul
            assert_eq(255u8.wrapping_mul(2u8), 254u8);
            assert_eq(255u8.wrapping_mul(255u8), 1u8);
            assert_eq(128u8.wrapping_mul(2u8), 0u8);

            // test u16 wrapping mul
            assert_eq(65535u16.wrapping_mul(2u16), 65534u16);
            assert_eq(65535u16.wrapping_mul(65535u16), 1u16);

            // test u32 wrapping mul
            assert_eq(0xffffffffu32.wrapping_mul(2u32), 0xfffffffeu32);
            assert_eq(0xffffffffu32.wrapping_mul(0xffffffffu32), 1u32);

            // test u64 wrapping mul
            // 0xffffffffffffffffu64 is 2^64 - 1
            assert_eq(0xffffffffffffffffu64.wrapping_mul(2u64), 0xfffffffffffffffeu64);
            assert_eq(0xffffffffffffffffu64.wrapping_mul(0xffffffffffffffffu64), 1u64);

            // test signed types
            assert_eq(127i8.wrapping_mul(2i8), -2i8);
            let val: i8 = -128;
            assert_eq(val.wrapping_mul(-1i8), -128i8);

            // test Field wrapping mul
            let six: Field = 6;
            let seven: Field = 7;
            let forty_two: Field = 42;
            let neg_two: Field = -2;
            let two: Field = 2;
            let neg_four: Field = -4;
            assert_eq(six.wrapping_mul(seven), forty_two);
            assert_eq(neg_two.wrapping_mul(two), neg_four);
        }

        // test wrapping operations is the same as the regular operations
        #[test]
        fn test_wrapping_vs_regular() {
            let u64_large = 0x123456789abcdef0u64;
            let u128_large = 0x123456789abcdef0123456789abcdef0u128;

            assert_eq(u64_large.wrapping_add(1u64), u64_large + 1u64);
            assert_eq(u64_large.wrapping_sub(1u64), u64_large - 1u64);
            assert_eq(u64_large.wrapping_mul(2u64), u64_large * 2u64);

            assert_eq(u128_large.wrapping_add(1u128), u128_large + 1u128);
            assert_eq(u128_large.wrapping_sub(1u128), u128_large - 1u128);
            assert_eq(u128_large.wrapping_mul(2u128), u128_large * 2u128);
        }

        #[test]
        fn test_field_wrapping_operations() {
            let zero: Field = 0;
            let one: Field = 1;
            let large_val = 0xffffffffffffffff;

            // test Field wrapping operations
            assert_eq(zero.wrapping_add(one), one);
            assert_eq(one.wrapping_add(large_val), one + large_val);
            assert_eq(zero.wrapping_sub(one), -one);
            assert_eq(one.wrapping_sub(large_val), one - large_val);
            assert_eq(zero.wrapping_mul(one), zero);
            assert_eq(one.wrapping_mul(large_val), large_val);

            // test Field basic operations
            assert_eq(zero.add(one), one);
            assert_eq(one.add(zero), one);
            assert_eq(one.sub(one), zero);
            assert_eq(one.mul(one), one);
            assert_eq(one.div(one), one);
            assert_eq(zero.neg(), zero);
            assert_eq(one.neg(), -one);
        }

    }

    mod split_functions {

        use crate::ops::arith::{split64, split_into_64_bit_limbs};

        // test split64 and split_into_64_bit_limbs functions
        #[test]
        fn test_split_functions() {
            let small_val = 0x123456789abcdefu128;
            let large_val = 0x123456789abcdef0123456789abcdef0u128;
            let max_val = 0xffffffffffffffffffffffffffffffffu128;

            // test split64 (unconstrained)
            // Safety: testing
            unsafe {
                let (lo, hi) = split64(small_val);
                assert_eq(lo, 0x123456789abcdefu64);
                assert_eq(hi, 0u64);

                let (lo2, hi2) = split64(large_val);
                assert_eq(lo2, 0x123456789abcdef0u64);
                assert_eq(hi2, 0x123456789abcdef0u64);
            }

            // test split_into_64_bit_limbs (constrained)
            let (lo3, hi3) = split_into_64_bit_limbs(small_val);
            assert_eq(lo3, 0x123456789abcdefu64);
            assert_eq(hi3, 0u64);

            let (lo4, hi4) = split_into_64_bit_limbs(large_val);
            assert_eq(lo4, 0x123456789abcdef0u64);
            assert_eq(hi4, 0x123456789abcdef0u64);

            let (lo5, hi5) = split_into_64_bit_limbs(max_val);
            assert_eq(lo5, 0xffffffffffffffffu64);
            assert_eq(hi5, 0xffffffffffffffffu64);
        }
    }

    mod traits {
        use crate::ops::arith::{
            Add, Div, Mul, Neg, Rem, Sub, WrappingAdd, WrappingMul, WrappingSub,
        };

        #[test]
        fn add() {
            assert_eq(1_u8.add(2), 3);
            assert_eq(1_u16.add(2), 3);
            assert_eq(1_u32.add(2), 3);
            assert_eq(1_u64.add(2), 3);
            assert_eq(1_u128.add(2), 3);
            assert_eq(1_i8.add(2), 3);
            assert_eq(1_i16.add(2), 3);
            assert_eq(1_i32.add(2), 3);
            assert_eq(1_i64.add(2), 3);
            assert_eq(1_Field.add(2), 3);
        }

        #[test]
        fn sub() {
            assert_eq(3_u8.sub(2), 1);
            assert_eq(3_u16.sub(2), 1);
            assert_eq(3_u32.sub(2), 1);
            assert_eq(3_u64.sub(2), 1);
            assert_eq(3_u128.sub(2), 1);
            assert_eq(3_i8.sub(2), 1);
            assert_eq(3_i16.sub(2), 1);
            assert_eq(3_i32.sub(2), 1);
            assert_eq(3_i64.sub(2), 1);
            assert_eq(3_Field.sub(2), 1);
        }

        #[test]
        fn mul() {
            assert_eq(3_u8.mul(2), 6);
            assert_eq(3_u16.mul(2), 6);
            assert_eq(3_u32.mul(2), 6);
            assert_eq(3_u64.mul(2), 6);
            assert_eq(3_u128.mul(2), 6);
            assert_eq(3_i8.mul(2), 6);
            assert_eq(3_i16.mul(2), 6);
            assert_eq(3_i32.mul(2), 6);
            assert_eq(3_i64.mul(2), 6);
            assert_eq(3_Field.mul(2), 6);
        }

        #[test]
        fn div() {
            assert_eq(6_u8.div(2), 3);
            assert_eq(6_u16.div(2), 3);
            assert_eq(6_u32.div(2), 3);
            assert_eq(6_u64.div(2), 3);
            assert_eq(6_u128.div(2), 3);
            assert_eq(6_i8.div(2), 3);
            assert_eq(6_i16.div(2), 3);
            assert_eq(6_i32.div(2), 3);
            assert_eq(6_i64.div(2), 3);
            assert_eq(6_Field.div(2), 3);
        }

        #[test]
        fn rem() {
            assert_eq(3_u8.rem(2), 1);
            assert_eq(3_u16.rem(2), 1);
            assert_eq(3_u32.rem(2), 1);
            assert_eq(3_u64.rem(2), 1);
            assert_eq(3_u128.rem(2), 1);
            assert_eq(3_i8.rem(2), 1);
            assert_eq(3_i16.rem(2), 1);
            assert_eq(3_i32.rem(2), 1);
            assert_eq(3_i64.rem(2), 1);
        }

        #[test]
        fn neg() {
            assert_eq(3_i8.neg(), -3);
            assert_eq(3_i16.neg(), -3);
            assert_eq(3_i32.neg(), -3);
            assert_eq(3_i64.neg(), -3);
        }

        #[test]
        fn wrapping_add() {
            assert_eq(255_u8.wrapping_add(2), 1);
            assert_eq(65535_u16.wrapping_add(2), 1);
            assert_eq(4294967295_u32.wrapping_add(2), 1);
            assert_eq(18446744073709551615_u64.wrapping_add(2), 1);
            assert_eq(340282366920938463463374607431768211455_u128.wrapping_add(2), 1);
            assert_eq(127_i8.wrapping_add(2), -127);
            assert_eq(32767_i16.wrapping_add(2), -32767);
            assert_eq(2147483647_i32.wrapping_add(2), -2147483647);
            assert_eq(9223372036854775807_i64.wrapping_add(2), -9223372036854775807);
            assert_eq(1_Field.wrapping_add(2), 3);
        }

        #[test]
        fn wrapping_sub() {
            assert_eq(0_u8.wrapping_sub(1), 255);
            assert_eq(0_u16.wrapping_sub(1), 65535);
            assert_eq(0_u32.wrapping_sub(1), 4294967295);
            assert_eq(0_u64.wrapping_sub(1), 18446744073709551615);
            assert_eq(0_u128.wrapping_sub(1), 340282366920938463463374607431768211455);
            assert_eq((-128_i8).wrapping_sub(1), 127);
            assert_eq((-32768_i16).wrapping_sub(1), 32767);
            assert_eq((-2147483648_i32).wrapping_sub(1), 2147483647);
            assert_eq((-9223372036854775808_i64).wrapping_sub(1), 9223372036854775807);
            assert_eq(3_Field.wrapping_sub(1), 2);
        }

        #[test]
        fn wrapping_mul() {
            assert_eq(255_u8.wrapping_mul(2), 254);
            assert_eq(65535_u16.wrapping_mul(2), 65534);
            assert_eq(4294967295_u32.wrapping_mul(2), 4294967294);
            assert_eq(18446744073709551615_u64.wrapping_mul(2), 18446744073709551614);
            assert_eq(
                340282366920938463463374607431768211455_u128.wrapping_mul(2),
                340282366920938463463374607431768211454,
            );
            assert_eq(127_i8.wrapping_mul(2), -2);
            assert_eq(32767_i16.wrapping_mul(2), -2);
            assert_eq(2147483647_i32.wrapping_mul(2), -2);
            assert_eq(9223372036854775807_i64.wrapping_mul(2), -2);
            assert_eq(2_Field.wrapping_mul(3), 6);
        }
    }
}

53.source:
// 2048-bit modular multiplication, checked rather than computed: the prover
// supplies the quotient and remainder of a * b by n (inputs.mjs), and the
// circuit checks a * b = q * n + r over the integers, in 18 limbs of 120 bits.
// Each column of the product is carried into the next; a carry is exact only
// if the column is a multiple of 2^120, and the range check on it fails
// otherwise. The result is congruent to a * b mod n, which is all RSA
// verification needs: the last remainder must equal the encoded message.

pub global LIMBS: u32 = 18;
global COLUMNS: u32 = 2 * LIMBS - 1;
global SHIFT_INV: Field = 1 / 0x1000000000000000000000000000000; // 2^-120
global CARRY_OFFSET: Field = 0x80000000000000000000000000000000; // 2^127

pub fn assert_limbs(x: [Field; LIMBS]) {
    for i in 0..LIMBS {
        x[i].assert_max_bit_size::<120>();
    }
}

// Requires a, b and n to be range-checked by the caller; checks q and r.
pub fn assert_mul_mod(
    a: [Field; LIMBS],
    b: [Field; LIMBS],
    q: [Field; LIMBS],
    r: [Field; LIMBS],
    n: [Field; LIMBS],
) {
    assert_limbs(q);
    assert_limbs(r);
    let mut columns: [Field; COLUMNS] = [0; COLUMNS];
    for i in 0..LIMBS {
        for j in 0..LIMBS {
            columns[i + j] += a[i] * b[j] - q[i] * n[j];
        }
    }
    for k in 0..LIMBS {
        columns[k] -= r[k];
    }
    // Every column is below 18 * 2^240 in size, so every carry is below 2^126.
    let mut carry: Field = 0;
    for k in 0..COLUMNS {
        carry = (columns[k] + carry) * SHIFT_INV;
        (carry + CARRY_OFFSET).assert_max_bit_size::<128>();
    }
    assert(carry == 0);
}

55.source:
// Prototype: the circom PAN circuit (../pan/circuits/pan-verifier.circom)
// rewritten in Noir, to be proved with Barretenberg's UltraHonk, which needs no
// per-circuit setup ceremony. It checks the same things:
//   - SHA-256 of the canonical record, as base64, in DigiLocker's exact
//     SignedInfo; SHA-1 of that SignedInfo; the RSA PKCS#1 v1.5 signature;
//   - the record's fixed head: a PAN record, status "A", issued through
//     DigiLocker by the Income Tax Department;
//   - the date of birth, gender, uid and <PAN> attributes where the prover's
//     hints say, each matched by its exact markup, inside the hashed bytes.
// It returns the key's hash, a per-verifier nullifier from the PAN number and
// uid, the hour DigiLocker verified the PAN, whether the holder was born on or
// before the verifier's date, and the gender if the holder reveals it. Both
// hashes are Poseidon2 (Barretenberg's), not the circom version's Poseidon.

mod bignum;
mod constants;
mod poseidon2;
mod sha1;

use constants::{
    BASE64, DIGEST_AT, DOC_HEAD, DOC_HEAD_LEN, EM_WITHOUT_HASH, FEMALE, GENDER_TAG, MALE, PAN_END,
    PAN_LEN, PAN_OFFSET, PAN_TAG, SIGNED_INFO_MIDSTATE, SIGNED_INFO_TAIL, TRANSGENDER, UID_TAG,
    VERIFIED_TAG,
};

global MAX_DOC_BYTES: u32 = 3584; // 56 SHA-256 blocks
global WINDOW: u32 = 1280; // gender, uid and <PAN> must end within it
global SHA256_IV: [u32; 8] =
    [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
global RSA_STEPS: u32 = 17; // 65537 = 2^16 + 1: sixteen squarings, then one multiplication

fn main(
    doc: [u8; MAX_DOC_BYTES], // canonical record, SHA-256 padding, then zeros
    doc_padded_length: u32,
    signature: [Field; bignum::LIMBS],
    modulus: [Field; bignum::LIMBS],
    rsa_q: [[Field; bignum::LIMBS]; RSA_STEPS],
    rsa_r: [[Field; bignum::LIMBS]; RSA_STEPS],
    gender_at: u32, // where ` gender="` starts
    uid_at: u32, // where ` uid="` starts (the Person's)
    pan_at: u32, // where `<PAN num="` starts
    reveal_gender: bool,
    dob_cutoff: pub u32, // YYYYMMDD
    nullifier_seed: pub Field,
    signal_hash: pub Field,
) -> pub (Field, Field, u32, bool, u8) {
    let _ = signal_hash; // bound to the proof as a public input

    // ---- 1. SHA-256 of the record ------------------------------------------
    assert(doc_padded_length % 64 == 0);
    assert(doc_padded_length <= MAX_DOC_BYTES);
    let blocks = doc_padded_length / 64;
    let mut state = SHA256_IV;
    for i in 0..(MAX_DOC_BYTES / 64) {
        let mut words: [u32; 16] = [0; 16];
        for j in 0..16 {
            let at = 64 * i + 4 * j;
            words[j] = ((doc[at] as u32) << 24)
                | ((doc[at + 1] as u32) << 16)
                | ((doc[at + 2] as u32) << 8)
                | (doc[at + 3] as u32);
        }
        let next = std::hash::sha256_compression(words, state);
        if i < blocks {
            state = next;
        }
    }

    // ---- 2. its base64 in SignedInfo, and SHA-1 of SignedInfo ---------------
    let mut digest: [u8; 32] = [0; 32];
    for i in 0..8 {
        digest[4 * i] = (state[i] >> 24) as u8;
        digest[4 * i + 1] = (state[i] >> 16) as u8;
        digest[4 * i + 2] = (state[i] >> 8) as u8;
        digest[4 * i + 3] = state[i] as u8;
    }
    let encoded = base64_digest(digest);
    let mut tail = SIGNED_INFO_TAIL;
    for i in 0..44 {
        tail[DIGEST_AT + i] = encoded[i];
    }
    let mut first: [u8; 64] = [0; 64];
    let mut second: [u8; 64] = [0; 64];
    for i in 0..64 {
        first[i] = tail[i];
        second[i] = tail[64 + i];
    }
    let h = sha1::compress(sha1::compress(SIGNED_INFO_MIDSTATE, first), second);

    // ---- 3. RSA PKCS#1 v1.5 with SHA-1: signature^65537 = EM mod n ----------
    bignum::assert_limbs(signature);
    bignum::assert_limbs(modulus);
    let mut x = signature;
    for step in 0..(RSA_STEPS - 1) {
        bignum::assert_mul_mod(x, x, rsa_q[step], rsa_r[step], modulus);
        x = rsa_r[step];
    }
    bignum::assert_mul_mod(x, signature, rsa_q[RSA_STEPS - 1], rsa_r[RSA_STEPS - 1], modulus);
    // EM's lowest 160 bits are H (h[0] most significant): limb 0 holds its low
    // 120 bits, limb 1 the other 40.
    let mut em = EM_WITHOUT_HASH;
    em[0] += (h[4] as Field)
        + (h[3] as Field) * 0x100000000
        + (h[2] as Field) * 0x10000000000000000
        + ((h[1] & 0xffffff) as Field) * 0x1000000000000000000000000;
    em[1] += ((h[1] >> 24) as Field) + (h[0] as Field) * 0x100;
    for i in 0..bignum::LIMBS {
        assert(rsa_r[RSA_STEPS - 1][i] == em[i]);
    }
    let pubkey_hash = poseidon2::hash(modulus);

    // ---- 4. the fixed head, and the date of birth after it ------------------
    for i in 0..DOC_HEAD_LEN {
        if (i < PAN_OFFSET) | (i >= PAN_OFFSET + PAN_LEN) {
            assert(doc[i] == DOC_HEAD[i]);
        }
    }
    let dob = date_value(doc, DOC_HEAD_LEN);
    assert(doc[DOC_HEAD_LEN + 10] == 34); // closing quote
    let born_by = dob <= dob_cutoff;

    // ---- 5. gender, uid and <PAN>, at the hinted places ---------------------
    // In order after the date of birth, and inside both the window and the
    // hashed bytes.
    assert(DOC_HEAD_LEN + 10 < gender_at);
    assert(gender_at < uid_at);
    assert(uid_at < pan_at);
    assert(pan_at + 61 <= WINDOW);
    assert(pan_at + 61 <= doc_padded_length, "the fields must lie in the hashed bytes");

    assert(matches(doc, gender_at, GENDER_TAG));
    let is_male = matches(doc, gender_at + 9, MALE);
    let is_female = matches(doc, gender_at + 9, FEMALE);
    let is_trans = matches(doc, gender_at + 9, TRANSGENDER);
    assert((is_male as u8) + (is_female as u8) + (is_trans as u8) == 1);
    let letter: u8 = if is_male {
        77 // M
    } else if is_female {
        70 // F
    } else {
        84 // T
    };
    let gender: u8 = if reveal_gender { letter } else { 0 };

    assert(matches(doc, uid_at, UID_TAG));
    assert(doc[uid_at + 38] == 34); // "
    assert(doc[uid_at + 39] == 62); // >, the Person's last attribute

    assert(matches(doc, pan_at, PAN_TAG));
    for i in 0..PAN_LEN {
        assert(doc[pan_at + 10 + i] == doc[PAN_OFFSET + i]); // the head's PAN number
    }
    assert(matches(doc, pan_at + 20, VERIFIED_TAG));
    // verifiedOn: DD-MM-YYYY HH:MM:SS
    let verified_date = date_value(doc, pan_at + 34);
    assert(doc[pan_at + 44] == 32); // space
    assert(doc[pan_at + 47] == 58); // :
    assert(doc[pan_at + 50] == 58);
    let verified_hour = verified_date * 100 + digit(doc[pan_at + 45]) * 10 + digit(doc[pan_at + 46]);
    assert(matches(doc, pan_at + 53, PAN_END));

    // ---- 6. nullifier ------------------------------------------------------
    let nullifier = poseidon2::hash(
        [nullifier_seed, pack::<PAN_LEN>(doc, PAN_OFFSET), pack::<16>(doc, uid_at + 6), pack::<16>(doc, uid_at + 22)],
    );

    (pubkey_hash, nullifier, verified_hour, born_by, gender)
}

// SHA-256 digest as base64: 43 characters, then "=".
fn base64_digest(d: [u8; 32]) -> [u8; 44] {
    let mut out: [u8; 44] = [0; 44];
    for g in 0..10 {
        let b0 = d[3 * g];
        let b1 = d[3 * g + 1];
        let b2 = d[3 * g + 2];
        out[4 * g] = BASE64[(b0 >> 2) as u32];
        out[4 * g + 1] = BASE64[(((b0 & 3) << 4) | (b1 >> 4)) as u32];
        out[4 * g + 2] = BASE64[(((b1 & 15) << 2) | (b2 >> 6)) as u32];
        out[4 * g + 3] = BASE64[(b2 & 63) as u32];
    }
    out[40] = BASE64[(d[30] >> 2) as u32];
    out[41] = BASE64[(((d[30] & 3) << 4) | (d[31] >> 4)) as u32];
    out[42] = BASE64[((d[31] & 15) << 2) as u32];
    out[43] = 61; // =
    out
}

fn matches<let N: u32>(doc: [u8; MAX_DOC_BYTES], at: u32, text: [u8; N]) -> bool {
    let mut all = true;
    for i in 0..N {
        all &= doc[at + i] == text[i];
    }
    all
}

// An ASCII digit's value; anything else fails.
fn digit(c: u8) -> u32 {
    assert((c >= 48) & (c <= 57));
    (c - 48) as u32
}

// DD-MM-YYYY at `at`, as the number YYYYMMDD.
fn date_value(doc: [u8; MAX_DOC_BYTES], at: u32) -> u32 {
    assert(doc[at + 2] == 45); // -
    assert(doc[at + 5] == 45);
    let day = digit(doc[at]) * 10 + digit(doc[at + 1]);
    let month = digit(doc[at + 3]) * 10 + digit(doc[at + 4]);
    let year = digit(doc[at + 6]) * 1000
        + digit(doc[at + 7]) * 100
        + digit(doc[at + 8]) * 10
        + digit(doc[at + 9]);
    year * 10000 + month * 100 + day
}

// N bytes as one integer, first byte lowest.
fn pack<let N: u32>(doc: [u8; MAX_DOC_BYTES], at: u32) -> Field {
    let mut acc: Field = 0;
    let mut scale: Field = 1;
    for i in 0..N {
        acc += (doc[at + i] as Field) * scale;
        scale *= 256;
    }
    acc
}

